return {
  heal: {
    hook: "activated",
    available: (H, actor) => actor.system.health.wounds.value > 0,
    async run(H, actor) {
      const allies = H.zone.allies(actor);
      if (!allies.length) {
        ui.notifications.warn("Remake: no allies in your area.");
        return false;
      }
      const id = await H.ask.one({
        title: "Remake",
        label: "Target Hunter",
        options: allies.map((h) => ({ value: h.id, label: h.name })),
      });
      if (!id) return false;
      const target = allies.find((h) => h.id === id);
      const statValue = await H.stat.total(actor, "wise");
      const result = await H.stat.roll(actor, {
        title: "Remake",
        cardTitle: "Wise",
        statLabel: "Wise",
        statValue,
        focusCount: H.resource.focusCount(actor),
        spendFocus: () => H.resource.adjust(actor, { focus: -1 }),
      }, { mode: H.zone.of(actor) === "Support" ? "adv" : "normal", useFocus: false });
      if (!result) return false;
      const outcome = result.chosen?.outcome?.label || "Failure";
      const healed = ["Success", "Superior Success", "Critical Success"].includes(outcome) ? 3 : 1;
      const esc = foundry.utils.escapeHTML;
      await result.roll.toMessage({
        speaker: ChatMessage.getSpeaker({ actor }),
        flavor: "Remake",
        content: `<div class="hollows-chat"><strong>${esc(actor.name)}</strong> uses <strong>Remake</strong> on <strong>${esc(target.name)}</strong>.<div>Wise ${result.chosen?.value}/${statValue} — ${outcome}.</div><div>Heals <strong>${healed}</strong> Wounds.</div></div>`,
      });
      await H.resource.adjust(actor, { wounds: -1 });
      await H.resource.adjust(target, { wounds: healed });
    },
  },
};
